var a=[{title:`Ce face mușchii să crească`,text:`Mușchii cresc ca răspuns la încărcarea mecanică repetată și la o refacere suficientă. Schimbările mari durează de obicei luni sau ani, nu câteva sesiuni de ridicare. A fi puternic și a arăta foarte musculos sunt rezultate diferite și poți alege obiective de antrenament care se potrivesc cu ce îți dorești.`},{title:`Ce arată studiile comparative`,text:`O meta-analiză din 2025 a constatat că femeile și bărbații au câștigat dimensiuni musculare relative în mare măsură similare cu programe comparabile de antrenament de forță, deși câștigurile absolute medii ale bărbaților au fost puțin mai mari. Asta nu este un motiv să descurajezi femeile să ridice greutăți. Arată că femeile pot câștiga mușchi și forță reale.`},{title:`Antrenează-te pentru ce îți dorești`,text:`Unele persoane vor o creștere musculară vizibilă. Altora le pasă mai mult de forța de zi cu zi, de sănătatea oaselor, de performanța sportivă sau de încredere. Volumul antrenamentului și alegerea exercițiilor pot urma aceste priorități. Antrenamentul de forță nu cere rutine de culturism sau greutăți mai mari în fiecare zi.`},{title:`Exemplu`,text:`Două sesiuni pe săptămână pentru tot corpul, cu genuflexiuni, ramat, împingeri și balansări din șold, pot îmbunătăți forța și funcția. Urmărește-ți performanța și nu-ți face griji că un singur antrenament îți va schimba brusc aspectul.`},{title:`Folosirea TrainUp`,text:`În Profil îți alegi obiectivul: condiție fizică generală, forță sau condiție fizică. Planul tău este construit din acel obiectiv, din nivelul tău, din echipamentul tău și din feedbackul tău după antrenamente și nu promite nicio formă anume a corpului.`}];var t=[{label:`Analiză sistematică din 2025: creșterea musculară la bărbați și femei`,url:`https://pubmed.ncbi.nlm.nih.gov/40028215/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};